<section class="container admin"><?php require __DIR__.'/_nav.php'?><h1><?=e($title)?></h1><form class="editor" method="post"><?=csrf_field()?><label>Judul<input name="title" maxlength="220" required value="<?=e($post['title']??'')?>"></label><label>Slug<input name="slug" maxlength="240" value="<?=e($post['slug']??'')?>"></label><?php if($post&&user()['role']==='admin'):?><label class="check"><input type="checkbox" name="change_slug"> Ganti slug secara eksplisit</label><?php endif?><label>Ringkasan<textarea name="excerpt" required><?=e($post['excerpt']??'')?></textarea></label><label>Isi HTML<textarea class="body" name="body" required><?=e($post['body']??'')?></textarea><small>HTML aman akan dipertahankan; skrip dan embed dibuang.</small></label><label>Kategori<select name="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($post['category_id']??null)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><fieldset><legend>Tag</legend><div class="checks"><?php foreach($tags as $t):?><label><input type="checkbox" name="tags[]" value="<?=$t['id']?>" <?=in_array($t['id'],$selected)?'checked':''?>><?=e($t['name'])?></label><?php endforeach?></div></fieldset><label>Sumber URL<input type="url" name="source_url" value="<?=e($post['source_url']??'')?>"></label><label>Meta title<input name="meta_title" maxlength="220" value="<?=e($post['meta_title']??'')?>"></label><label>Meta description<textarea name="meta_description" maxlength="320"><?=e($post['meta_description']??'')?></textarea></label><?php if(user()['role']==='admin'):?><label class="check"><input type="checkbox" name="is_featured" <?=!empty($post['is_featured'])?'checked':''?>> Artikel unggulan</label><label class="check"><input type="checkbox" name="is_editor_pick" <?=!empty($post['is_editor_pick'])?'checked':''?>> Pilihan editor</label><?php endif?><label>Status<select name="status"><option value="draft">Draf</option><option value="pending" <?=($post['status']??'')==='pending'?'selected':''?>>Ajukan tinjauan</option><?php if(user()['role']==='admin'):?><option value="published" <?=($post['status']??'')==='published'?'selected':''?>>Terbit</option><option value="archived" <?=($post['status']??'')==='archived'?'selected':''?>>Arsip</option><?php endif?></select></label><button class="button">Simpan artikel</button></form></section>
